"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { ChevronDown, ChevronRight, File, Folder } from "./icons";

// Tree Item: generated by UIX from the design system. Same variants and sizes as the Figma component.

const treeItemVariants = cva(
  "flex w-full cursor-pointer items-center text-left transition-colors h-8 pr-2 gap-1-5 rounded-sm text-body-small text-fg-primary hover:bg-subtle focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus aria-selected:bg-brand-subtle aria-selected:text-fg-brand aria-selected:hover:bg-brand-subtle [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-icon-secondary [&[aria-selected=true]_svg]:text-icon-brand",
  {
    variants: {
      level: {
        "1": "pl-2",
        "2": "pl-[28px]",
        "3": "pl-12",
      },
    },
    defaultVariants: {
      level: "1",
    },
  },
);

export interface TreeProps
  extends React.HTMLAttributes<HTMLDivElement> {}

const Tree = React.forwardRef<HTMLDivElement, TreeProps>(
  ({ className, ...props }, ref) => (
    <div data-slot="tree-view" data-kind="surface" ref={ref} role="tree" className={cn("flex flex-col p-2 gap-0-5 bg-surface border border-line-default rounded-lg", className)} {...props} />
  ),
);
Tree.displayName = "Tree";

export interface TreeItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof treeItemVariants> {
  selected?: boolean;
  /** True / false for a folder (open / closed), left out for a file. */
  expanded?: boolean;
}

const TreeItem = React.forwardRef<HTMLButtonElement, TreeItemProps>(({ className, level, selected = false, expanded, children, ...props }, ref) => (
  <button ref={ref} type="button" role="treeitem" data-slot="tree-item" data-kind={selected ? "chip" : void 0} aria-selected={selected} aria-expanded={expanded} className={cn(treeItemVariants({ level }), !selected && "skin-quiet", className)} {...props}>
    {expanded === void 0 ? <span aria-hidden className="size-4" /> : expanded ? <ChevronDown aria-hidden /> : <ChevronRight aria-hidden />}
    {expanded === void 0 ? <File aria-hidden /> : <Folder aria-hidden />}
    <span className="min-w-0 flex-1 truncate">{children}</span>
  </button>
));
TreeItem.displayName = "TreeItem";

export { Tree, TreeItem, treeItemVariants };
